 function editRequest(c){modal('Correct the request.',`<p>The original source stays saved. The doctor and insurer will check these details again before booking.</p>${c.correction?`<div class="team-explainer"><strong>What needs fixing</strong><p>${esc(c.correction.reason)}</p></div>`:''}<form>${field('patient_name','Fictional patient name','text',c.patient_name)}${select('procedure','Ordered test',['MRI brain','MRI knee','MRI spine'],c.procedure)}${field('order_note','Sample doctor’s request','textarea',c.order_note)}${field('doctor_note','Sample supporting note','textarea',c.doctor_note||'')}${review}<p class="error-message" data-error role="alert"></p>${button('Save corrected request','type="submit"','primary')}</form>`,form=>saveException(c,'edit_request',{...Object.fromEntries(new FormData(form)),reviewed:form.elements.reviewed.checked}));}
