  return `${claims.length||insurance.length?`<details class="team-details"><summary>Response evidence (${claims.length+insurance.length})</summary>${[...insurance,...claims].map(r=>`<article class="team-response"><strong>${esc(r.status)} · ${esc(r.reference)}</strong><p>${esc(r.evidence)}</p><small>${esc(r.actor)} · ${date(r.at)}</small></article>`).join('')}</details>`:''}`;
